  const SaveSystem = {
    KEY: 'starfighter_save_v1',
    
    defaultData: {
      coins: 0,
      ownedWeapons: ['basic'],
      ownedSkins: ['default'],
      currentWeapon: 'basic',
      currentSkin: 'default',
      highScores: {
        classic: [],
        endless: [],
        bossRush: []
      }
    },
    
    data: null,
    
    load() {
      try {
        const saved = localStorage.getItem(this.KEY);
        if (saved) {
          this.data = Object.assign({}, this.defaultData, JSON.parse(saved));
        } else {
          this.data = JSON.parse(JSON.stringify(this.defaultData));
        }
      } catch (e) {
        this.data = JSON.parse(JSON.stringify(this.defaultData));
      }
      return this.data;
    },
    
    save() {
      try {
        localStorage.setItem(this.KEY, JSON.stringify(this.data));
      } catch (e) {}
    },
    
    addCoins(amount) {
      this.data.coins += amount;
      this.save();
      return this.data.coins;
    },
    
    spendCoins(amount) {
      if (this.data.coins >= amount) {
        this.data.coins -= amount;
        this.save();
        return true;
      }
      return false;
    },
    
    buyWeapon(weaponId) {
      const weapon = WEAPON_SHOP[weaponId];
      if (!weapon) return false;
      if (this.data.ownedWeapons.includes(weaponId)) return false;
      if (this.data.coins < weapon.price) return false;
      
      this.data.coins -= weapon.price;
      this.data.ownedWeapons.push(weaponId);
      this.save();
      return true;
    },
    
    buySkin(skinId) {
      const skin = SKIN_SHOP[skinId];
      if (!skin) return false;
      if (this.data.ownedSkins.includes(skinId)) return false;
      if (this.data.coins < skin.price) return false;
      
      this.data.coins -= skin.price;
      this.data.ownedSkins.push(skinId);
      this.save();
      return true;
    },
    
    equipWeapon(weaponId) {
      if (this.data.ownedWeapons.includes(weaponId)) {
        this.data.currentWeapon = weaponId;
        this.save();
        return true;
      }
      return false;
    },
    
    equipSkin(skinId) {
      if (this.data.ownedSkins.includes(skinId)) {
        this.data.currentSkin = skinId;
        this.save();
        return true;
      }
      return false;
    }
  };

