  // ============================================================
  // 实体类
  // ============================================================

  class Particle {
    constructor(x, y, color, speed, life) {
      this.position = new Vector2(x, y);
      this.color = color;
      this.speed = speed;
      this.life = life;
      this.maxLife = life;
      this.alive = true;
      
      const angle = Math.random() * Math.PI * 2;
      this.velocity = new Vector2(
        Math.cos(angle) * this.speed,
        Math.sin(angle) * this.speed
      );
      
      this.size = Math.random() * 4 + 2;
    }

    update(deltaTime) {
      if (!this.alive) return;
      
      this.position.add(this.velocity);
      this.life -= deltaTime;
      this.size *= 0.98;
      
      if (this.life <= 0) {
        this.alive = false;
      }
    }

    render(ctx) {
      if (!this.alive) return;
      
      ctx.save();
      
      const alpha = this.life / this.maxLife;
      ctx.globalAlpha = alpha;
      ctx.fillStyle = this.color;
      ctx.shadowColor = this.color;
      ctx.shadowBlur = 10;
      
      ctx.beginPath();
      ctx.arc(this.position.x, this.position.y, this.size, 0, Math.PI * 2);
      ctx.fill();
      
      ctx.restore();
    }

    reset() {
      this.alive = false;
    }
  }

  class FloatingText {
    constructor(x, y, text, color) {
      this.position = new Vector2(x, y);
      this.text = text;
      this.color = color || '#ffffff';
      this.life = 1.0;
      this.maxLife = 1.0;
      this.alive = true;
      this.velocity = new Vector2(0, -2);
      this.fontSize = 16;
    }

    update(deltaTime) {
      if (!this.alive) return;
      
      this.position.add(this.velocity);
      this.velocity.y *= 0.95;
      this.life -= deltaTime;
      
      if (this.life <= 0) {
        this.alive = false;
      }
    }

    render(ctx) {
      if (!this.alive) return;
      
      ctx.save();
      
      const alpha = this.life / this.maxLife;
      ctx.globalAlpha = alpha;
      ctx.fillStyle = this.color;
      ctx.font = 'bold ' + this.fontSize + 'px "Microsoft YaHei", Arial';
      ctx.textAlign = 'center';
      ctx.shadowColor = this.color;
      ctx.shadowBlur = 10;
      
      ctx.fillText(this.text, this.position.x, this.position.y);
      
      ctx.restore();
    }

    reset() {
      this.alive = false;
    }
  }

  class Explosion {
    constructor(x, y, radius, damage, game) {
      this.position = new Vector2(x, y);
      this.radius = 0;
      this.maxRadius = radius || 80;
      this.damage = damage || 50;
      this.alive = true;
      this.life = 0.3;
      this.maxLife = 0.3;
      this.game = game;
      this.hasDamaged = false;
      
      if (game) {
        for (let i = 0; i < 20; i++) {
          const p = new Particle(x, y, '#ff6600', 3 + Math.random() * 4, 0.5 + Math.random() * 0.3);
          p.size = 3 + Math.random() * 4;
          game.entities.particles.push(p);
        }
        game.renderer.setShake(10);
      }
    }

    update(deltaTime) {
      if (!this.alive) return;
      
      this.radius += (this.maxRadius / this.maxLife) * deltaTime;
      this.life -= deltaTime;
      
      if (!this.hasDamaged && this.game) {
        this.hasDamaged = true;
        this.game.entities.enemies.forEach(enemy => {
          if (!enemy.alive) return;
          const dx = enemy.position.x - this.position.x;
          const dy = enemy.position.y - this.position.y;
          const dist = Math.sqrt(dx * dx + dy * dy);
          if (dist < this.maxRadius + enemy.radius) {
            enemy.takeDamage(this.damage);
          }
        });
      }
      
      if (this.life <= 0) {
        this.alive = false;
      }
    }

    render(ctx) {
      if (!this.alive) return;
      
      ctx.save();
      
      const alpha = this.life / this.maxLife;
      ctx.globalAlpha = alpha * 0.6;
      
      const gradient = ctx.createRadialGradient(
        this.position.x, this.position.y, 0,
        this.position.x, this.position.y, this.radius
      );
      gradient.addColorStop(0, '#ffffff');
      gradient.addColorStop(0.3, '#ffff00');
      gradient.addColorStop(0.6, '#ff6600');
      gradient.addColorStop(1, 'rgba(255, 0, 0, 0)');
      
      ctx.fillStyle = gradient;
      ctx.beginPath();
      ctx.arc(this.position.x, this.position.y, this.radius, 0, Math.PI * 2);
      ctx.fill();
      
      ctx.restore();
    }

    reset() {
      this.alive = false;
    }
  }

  class Bullet {
    constructor(x, y, vx, vy, damage, owner) {
      this.position = new Vector2(x, y);
      this.velocity = new Vector2(vx, vy);
      this.damage = damage;
      this.owner = owner;
      this.size = owner === 'player' ? 6 : 8;
      this.radius = this.size / 2;
      this.alive = true;
      
      this.collider = {
        x: this.position.x - this.size,
        y: this.position.y - this.size,
        width: this.size * 2,
        height: this.size * 2
      };
      
      this.target = null;
      this.isHoming = false;
    }

    update(deltaTime, game) {
      if (!this.alive) return;
      
      if (this.isHoming && this.target && this.target.alive) {
        const dx = this.target.position.x - this.position.x;
        const dy = this.target.position.y - this.position.y;
        const distance = Math.sqrt(dx * dx + dy * dy);
        
        if (distance > 0) {
          this.velocity.x += (dx / distance) * 0.5;
          this.velocity.y += (dy / distance) * 0.5;
          
          const speed = Math.sqrt(this.velocity.x * this.velocity.x + this.velocity.y * this.velocity.y);
          if (speed > 6) {
            this.velocity.x = (this.velocity.x / speed) * 6;
            this.velocity.y = (this.velocity.y / speed) * 6;
          }
        }
      }
      
      this.position.add(this.velocity);
      this.updateCollider();
      
      if (this.position.y < -50 || this.position.y > 770 ||
          this.position.x < -50 || this.position.x > 530) {
        this.alive = false;
      }
    }

    updateCollider() {
      this.collider.x = this.position.x - this.size;
      this.collider.y = this.position.y - this.size;
      this.collider.width = this.size * 2;
      this.collider.height = this.size * 2;
    }

    destroy() {
      this.alive = false;
    }

    render(ctx) {
      if (!this.alive) return;
      
      ctx.save();
      
      ctx.translate(this.position.x, this.position.y);
      
      if (this.owner === 'player') {
        if (this.isLaser) {
          ctx.fillStyle = '#00ffff';
          ctx.shadowColor = '#00ffff';
          ctx.shadowBlur = 20;
          ctx.fillRect(-3, -this.size * 2, 6, this.size * 4);
        } else if (this.explosive) {
          ctx.fillStyle = '#ff6600';
          ctx.shadowColor = '#ff6600';
          ctx.shadowBlur = 15;
          ctx.beginPath();
          ctx.arc(0, 0, this.size, 0, Math.PI * 2);
          ctx.fill();
          ctx.fillStyle = '#ffff00';
          ctx.beginPath();
          ctx.arc(0, 0, this.size * 0.5, 0, Math.PI * 2);
          ctx.fill();
        } else {
          ctx.fillStyle = this.isCrit ? '#ffff00' : '#00ffff';
          ctx.shadowColor = this.isCrit ? '#ffff00' : '#00ffff';
          ctx.shadowBlur = this.isCrit ? 15 : 10;
          
          ctx.beginPath();
          ctx.moveTo(0, -this.size);
          ctx.lineTo(-this.size * 0.5, this.size * 0.5);
          ctx.lineTo(this.size * 0.5, this.size * 0.5);
          ctx.closePath();
          ctx.fill();
        }
      } else {
        ctx.fillStyle = '#ff00ff';
        ctx.shadowColor = '#ff00ff';
        ctx.shadowBlur = 10;
        
        ctx.beginPath();
        ctx.arc(0, 0, this.size, 0, Math.PI * 2);
        ctx.fill();
        
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.arc(0, 0, this.size * 0.4, 0, Math.PI * 2);
        ctx.fill();
      }
      
      ctx.restore();
    }

    reset() {
      this.alive = false;
      this.target = null;
      this.isHoming = false;
    }
  }

